import axios from "axios";
import { useState } from "react";
import { FormGroup } from "../../auth/components/FormGroup";
import { NavbarDashboard } from "@/app/components/navbar/NavbarDashboard";

const api = axios.create({
    baseURL: "http://localhost:8002/ride/status/",
    headers: {
        "content-type": "applcation-json"
    }, 
    withCredentials: true
});

export default function ApplyRide() {
      const [loading , setLoading] = useState<boolean>(false);
      const [error, setError] = useState<string | null>(null);
      const [AadhaarNumber , setAadhaarNumber] = useState<number>();
      const [pancardNumber , setPanCardNumber] = useState<number>();
      const [location , setLoaction] = useState<string>();


    return (
        <>
        <NavbarDashboard />
        <div className="min-h-screen bg-[#0A111A] text-white flex flex-col font-sans max-w-md mx-auto relative">
          {/* Header */}
          <div className="flex items-center px-6 py-5 border-b border-gray-800">
            <button className="mr-4 text-gray-300 hover:text-white transition-colors">
              {/* Back Arrow SVG */}
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M19 12H5M12 19l-7-7 7-7" />
              </svg>
            </button>
            <h1 className="text-xl font-semibold">Verification Setup</h1>
          </div>
    
          <div className="p-6 flex-1 flex flex-col">
            {/* Progress Bar */}
            <div className="flex justify-between items-end mb-2">
              <span className="text-xs font-bold text-[#D08F70] tracking-wider uppercase">Verification Progress</span>
              <span className="text-xs font-bold text-[#3B82F6] tracking-wider uppercase">Step 1 of 3</span>
            </div>
            <div className="h-1.5 w-full bg-gray-800 rounded-full mb-8 overflow-hidden">
              <div className="h-full bg-[#52B6F9] w-1/3 rounded-full"></div>
            </div>
    
            {/* Title and Description */}
            <h2 className="text-2xl font-bold mb-2">Verify Identity</h2>
            <p className="text-gray-400 text-sm mb-8 leading-relaxed">
              Please provide your government issued IDs to ensure a secure ride experience.
            </p>
    
            {/* Form Fields */}
            <div className="space-y-6 flex-1">
              {/* Aadhaar Input */}
              <div>
                <label className="block text-xs font-bold text-[#D08F70] tracking-wider uppercase mb-2">
                  Aadhaar Number
                </label>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="XXXX XXXX XXXX"
                    value={AadhaarNumber || ''}
                    onChange={(e) => setAadhaarNumber(Number(e.target.value) || undefined)}
                    className="w-full bg-[#131E2B] border border-transparent focus:border-blue-500 rounded-lg px-4 py-3.5 text-white placeholder-gray-600 outline-none transition-colors font-mono tracking-widest"
                  />
                  <div className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-500">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
                      <line x1="16" y1="2" x2="16" y2="6"></line>
                      <line x1="8" y1="2" x2="8" y2="6"></line>
                      <line x1="3" y1="10" x2="21" y2="10"></line>
                      <path d="M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01M16 18h.01"></path>
                    </svg>
                  </div>
                </div>
              </div>
    
              {/* PAN Input */}
              <div>
                <label className="block text-xs font-bold text-[#D08F70] tracking-wider uppercase mb-2">
                  Pan Card Number
                </label>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="ABCDE1234F"
                    value={pancardNumber || ''}
                    onChange={(e) => setPanCardNumber(Number(e.target.value) || undefined)}
                    className="w-full bg-[#131E2B] border border-transparent focus:border-blue-500 rounded-lg px-4 py-3.5 text-white placeholder-gray-600 outline-none transition-colors font-mono tracking-widest uppercase"
                  />
                  <div className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-500">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <rect x="2" y="4" width="20" height="16" rx="2" ry="2"></rect>
                      <line x1="2" y1="10" x2="22" y2="10"></line>
                    </svg>
                  </div>
                </div>
              </div>
    
              {/* Current Location */}
              <div>
                <label className="block text-xs font-bold text-[#D08F70] tracking-wider uppercase mb-2">
                  Current Location
                </label>
                <div className="bg-[#131E2B] rounded-lg p-4">
                  <div className="flex items-start mb-4">
                    <div className="bg-[#1A2A3A] p-2 rounded-full mr-4 flex-shrink-0 mt-1 text-[#52B6F9]">
                      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <circle cx="12" cy="12" r="10"></circle>
                        <circle cx="12" cy="12" r="3"></circle>
                        <line x1="12" y1="2" x2="12" y2="5"></line>
                        <line x1="12" y1="19" x2="12" y2="22"></line>
                        <line x1="2" y1="12" x2="5" y2="12"></line>
                        <line x1="19" y1="12" x2="22" y2="12"></line>
                      </svg>
                    </div>
                    <div>
                      <div className="text-white font-medium mb-1">Connaught Place, New Delhi</div>
                      <div className="text-[10px] font-bold text-gray-400 tracking-wider uppercase">Required for verification</div>
                    </div>
                  </div>
                  <button className="w-full bg-[#0B1320] text-[#52B6F9] hover:bg-gray-900 transition-colors font-medium rounded-lg py-3 flex items-center justify-center border border-gray-800">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mr-2">
                      <path d="M21 2v6h-6"></path>
                      <path d="M3 12a9 9 0 0 1 15-6.7L21 8"></path>
                      <path d="M3 22v-6h6"></path>
                      <path d="M21 12a9 9 0 0 1-15 6.7L3 16"></path>
                    </svg>
                    Update Location
                  </button>
                </div>
              </div>
            </div>
    
            {/* Continue Button */}
            <div className="mt-8 mb-4">
              <button 
                className="w-full bg-[#6CD0FF] hover:bg-[#5BBDF2] text-[#0A111A] font-semibold text-lg py-4 rounded-xl flex items-center justify-center transition-colors shadow-[0_0_15px_rgba(108,208,255,0.3)] disabled:opacity-50"
                disabled={loading}
              >
                {loading ? 'Processing...' : 'Continue'}
                {!loading && (
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="ml-2">
                    <path d="M5 12h14"></path>
                    <path d="M12 5l7 7-7 7"></path>
                  </svg>
                )}
              </button>
            </div>
          </div>
        </div>
        </>
    )
}