"use client";
import { useState } from "react";

export const NavbarDashboard = () => {
    const [loading, setLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);

    const submitlogo = () => {
        setLoading(true);
        setError(null);

        try {
            // Add navigation or logo click logic here
        } catch {
            setError("Something went wrong");
        }

        setTimeout(() => {
            setLoading(false);
        }, 2000);
    }

    return (
        <>
            {/* Full Page Loading Overlay */}
            {loading && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm">
                    <div className="flex flex-col items-center">
                        <div className="w-12 h-12 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
                        <p className="mt-4 text-white font-semibold text-lg">Loading...</p>
                    </div>
                </div>
            )}

            {/* Navbar Layout */}
            <nav className="w-full bg-white shadow-md p-4 flex justify-between items-center relative z-40">
                <div 
                    className="text-2xl font-bold cursor-pointer text-orange-500 hover:text-orange-600 transition"
                    onClick={submitlogo}
                >
                    Logo
                </div>
                <div>
                    {/* Add other navbar links/items here */}
                    {error && <span className="text-red-500 mr-4">{error}</span>}
                    <button className="px-4 py-2 bg-gray-100 rounded-lg hover:bg-gray-200">
                        Profile
                    </button>
                </div>
            </nav>
        </>
    )
}